'use strict';
let buildingFeatures=[],buildingLayer=null,inspectionPoint=null,buildingAttribution='Building footprints © <a href="https://github.com/microsoft/CanadianBuildingFootprints">Microsoft</a> · <a href="https://opendatacommons.org/licenses/odbl/1-0/">ODbL</a>';
const inspectionLayer=L.layerGroup().addTo(map);
map.createPane('buildingPane');map.getPane('buildingPane').style.zIndex=410;
const buildingRenderer=L.canvas({pane:'buildingPane',padding:.5});
function displayBuildingLayer(){if(!buildingLayer)return;if($('buildingsvisible').checked){buildingLayer.addTo(map);map.attributionControl.addAttribution(buildingAttribution)}else{map.removeLayer(buildingLayer);map.attributionControl.removeAttribution(buildingAttribution)}}
$('buildingsvisible').onchange=displayBuildingLayer;
function inspectStructures(coord){inspectionPoint=coord;const radius=Number($('buildingradius').value),found=buildingFeatures.filter(f=>map.distance(coord,[f.properties.centre[1],f.properties.centre[0]])<=radius);inspectionLayer.clearLayers();L.circle(coord,{radius,color:'#a05e2d',weight:2,fillColor:'#b7783f',fillOpacity:.07,interactive:false}).addTo(inspectionLayer);$('buildinginspection').textContent=`${found.length} detected structures within ${radius.toLocaleString()} m of ${coord.map(n=>n.toFixed(5)).join(', ')}. Home count and occupancy unverified. Only footprints in the Response Area subset are counted; results near its edge may omit nearby structures outside the outline.`;$('usebuildingcluster').hidden=false;cancelMode()}
$('inspectbuildings').onclick=()=>startMode('inspect-buildings','Click a point to count detected structures within the selected radius. The count is not a count of homes.');
$('buildingradius').onchange=()=>{if(inspectionPoint)inspectStructures(inspectionPoint)};
map.on('click',e=>{if(mode==='inspect-buildings')inspectStructures([e.latlng.lat,e.latlng.lng])});
$('usebuildingcluster').onclick=()=>{if(!inspectionPoint)return;const radius=Number($('buildingradius').value),count=buildingFeatures.filter(f=>map.distance(inspectionPoint,[f.properties.centre[1],f.properties.centre[0]])<=radius).length;planEdit('cluster',null,inspectionPoint,{name:'Structure cluster — review needed',countbasis:`Microsoft footprints: ${count} detected structures with centres within ${radius} m. Dwellings not verified.`,notes:'Machine-detected structures include possible homes, garages, sheds and other buildings. Establish residential use and dwelling count before using home-count screening.'})};
fetch('buildings.geojson').then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.json()}).then(data=>{if(data.type!=='FeatureCollection')throw Error('Invalid building data');buildingFeatures=data.features;buildingLayer=L.geoJSON(data,{pane:'buildingPane',renderer:buildingRenderer,style:{color:'#845230',weight:1,fillColor:'#b38650',fillOpacity:.5},onEachFeature:(f,layer)=>{layer.bindTooltip('Detected building · use unknown');layer.on('click',e=>{if(mode==='inspect-buildings'){inspectStructures([e.latlng.lat,e.latlng.lng]);return}if(mode)return;if(typeof evaluationBuildingClick==='function'&&evaluationBuildingClick(f))return;layer.bindPopup('<b>Detected building footprint</b><br>Use / occupancy: unknown<br>Machine-generated outline; not a verified dwelling.<br>Individual imagery date: unknown.<br><small>© Microsoft · ODbL</small>').openPopup()})}});displayBuildingLayer();$('buildingstatus').textContent=`${buildingFeatures.length.toLocaleString()} detected structures · use unverified`;$('buildingcount').textContent=`${buildingFeatures.length.toLocaleString()} machine-detected footprints have centres inside the uploaded Response Area outline. Full outlines are retained. Garages, sheds and other structures may be included; missing buildings and older imagery are possible.`;$('inspectbuildings').disabled=false;window.dispatchEvent(new Event('geodata-ready'))}).catch(e=>{$('buildingstatus').textContent='Building layer unavailable';$('buildingcount').textContent='Could not load the local footprint subset. Reload to try again.';console.error('Building layer:',e.message)});
